// Converts the cburnett SVG piece set (by Colin M.L. Burnett, CC BY-SA 3.0,
// as distributed by lichess.org) into a TS module of XML strings for SvgXml.
const fs = require('fs');
const path = require('path');

const dir = path.join(__dirname, 'pieces');
const out = {};
for (const f of fs.readdirSync(dir).filter(n => n.endsWith('.svg')).sort()) {
  out[f.replace('.svg', '')] = fs
    .readFileSync(path.join(dir, f), 'utf8')
    .replace(/\s*style="[^"]*"/, '')
    .trim();
}
const body =
  '// Generated by scripts/gen-pieces.js — do not edit.\n' +
  '// cburnett piece set by Colin M.L. Burnett, CC BY-SA 3.0.\n' +
  `export const PIECE_XML: Record<string, string> = ${JSON.stringify(out, null, 2)};\n`;
fs.writeFileSync(path.join(__dirname, '..', 'src', 'chess', 'pieces.ts'), body);
console.log('wrote', Object.keys(out).length, 'pieces');
